    async def test_list_pending_review_success(self, client: AsyncClient, db, test_user: User): await _seed_router_matches(db, test_user, [ReconciliationStatus.PENDING_REVIEW, ReconciliationStatus.PENDING_REVIEW]); response = await client.get('/reconciliation/pending'); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert isinstance(data, dict); assert 'items' in data; assert 'total' in data
