        match = create_test_match(db, transaction, journal_entry_ids=[str(entry.id)]); db.add(match); await db.commit(); response = await client.patch(f'/reconciliation/matches/{match.id}', json={'action': 'accept'}); assert response.status_code == status.HTTP_200_OK; assert response.json()['status'] == ReconciliationStatusEnum.ACCEPTED.value
