    async def test_AC_reconciliation_review_queue_15_filters_unmatched_by_statement(self, client: AsyncClient, db, test_user: User): selected_statement, (selected_txn,) = await _seed_router_txns(db, test_user, count=1); _, (other_txn,) = await _seed_router_txns(db, test_user, count=1); foreign_user = User(email=f'statement-scope-{uuid4()}@example.com', hashed_password='hashed'); db.add(foreign_user); await db.flush(); foreign_statement, (foreign_txn,) = await _seed_router_txns(db, foreign_user, count=1); scoped = await client.get('/reconciliation/unmatched', params={'statement_id': str(selected_statement.id)}); assert scoped.status_code == status.HTTP_200_OK; assert scoped.json()['total'] == 1; assert [item['id'] for item in scoped.json()['items']] == [str(selected_txn.id)]; foreign = await client.get('/reconciliation/unmatched', params={'statement_id': str(foreign_statement.id)}); assert foreign.status_code == status.HTTP_404_NOT_FOUND; assert 'Statement' in foreign.json()['detail']
    async def test_AC_reconciliation_review_queue_15_statement_without_document_is_empty(self, client: AsyncClient, db, test_user: User): statement = await create_test_statement(db, test_user); statement.uploaded_document_id = None; await db.commit(); response = await client.get('/reconciliation/unmatched', params={'statement_id': str(statement.id)}); assert response.status_code == status.HTTP_200_OK; assert response.json() == {'items': [], 'total': 0}
    async def test_submit_reviewed_disposition_from_unmatched_success(self, client: AsyncClient, db, test_user: User): _, _, transaction, expense = await _seed_expense_setup(db, test_user, expense_name='Expense - Dining'); payload = {'intent': 'expense', 'counter_account_id': str(expense.id), 'category': 'DINING', 'rationale': 'Reviewed against the merchant and receipt.'}; response = await client.post(f'/reconciliation/unmatched/{transaction.id}/reviewed-dispositions', json=payload); assert response.status_code == status.HTTP_200_OK; data = response.json(); assert {'id', 'entry_date', 'memo', 'status', 'total_amount'} <= data.keys(); entries_result = await db.execute(select(JournalEntry).where(JournalEntry.user_id == test_user.id).where(JournalEntry.source_type.in_(STATEMENT_SOURCE_TYPES)).where(JournalEntry.source_id == transaction.id)); assert len(entries_result.scalars().all()) == 1; traces = (await db.execute(select(TraceRecordRow).where(TraceRecordRow.scope_id == str(test_user.id)).where(TraceRecordRow.target_id == str(transaction.id)).order_by(TraceRecordRow.occurred_at, TraceRecordRow.id))).scalars().all(); assert len(traces) == 4; manual = next((row for row in traces if row.assertion_kind == 'economic_intent')); assert manual.record_type is TraceRecordType.OBSERVATION; assert manual.authority_package == 'reconciliation'; assert manual.authority_tier == 'CODE-ONLY'; assert manual.provenance == 'manual'; assert manual.execution_stage == 'manual.adjudication'; assert manual.score is None; assert sum((row.record_type is TraceRecordType.DECISION for row in traces)) == 2; assert all((row.result is TraceResult.AUTHORITATIVE for row in traces if row.record_type is TraceRecordType.DECISION)); classifications = await db.execute(select(TransactionClassification).where(TransactionClassification.atomic_txn_id == transaction.id)); assert classifications.scalars().all() == []
    async def test_submit_reviewed_disposition_auto_binds_unmapped_statement_account(self, client: AsyncClient, db, test_user: User): statement = await create_test_statement(db, test_user, account_id=None, institution='Standard Chartered Bank', account_last4='9988', currency='SGD'); expense = Account(user_id=test_user.id, name=f'Expense - Unmapped Statement {uuid4().hex[:8]}', type=AccountType.EXPENSE, currency='SGD'); transaction = create_test_transaction(db, statement, amount=Decimal('88.50')); db.add_all([expense, transaction]); await db.commit(); response = await client.post(f'/reconciliation/unmatched/{transaction.id}/reviewed-dispositions', json={'intent': 'expense', 'counter_account_id': str(expense.id), 'category': 'DINING', 'rationale': 'Adjudicating unmatched transaction before Stage 1 confirmation.'}); assert response.status_code == status.HTTP_200_OK; await db.refresh(statement); assert statement.account_id is not None; custody_account = await db.get(Account, statement.account_id); assert custody_account is not None; assert custody_account.name == 'Standard Chartered Bank *9988'; assert custody_account.type == AccountType.ASSET; assert custody_account.currency == 'SGD'; second_statement = await create_test_statement(db, test_user, account_id=None, institution='Standard Chartered Bank', account_last4='9988', currency='SGD'); second_txn = create_test_transaction(db, second_statement, amount=Decimal('42.00')); db.add(second_txn); await db.commit(); second_response = await client.post(f'/reconciliation/unmatched/{second_txn.id}/reviewed-dispositions', json={'intent': 'expense', 'counter_account_id': str(expense.id), 'category': 'DINING', 'rationale': 'Second unmapped statement reuses existing custody account.'}); assert second_response.status_code == status.HTTP_200_OK; await db.refresh(second_statement); assert second_statement.account_id == custody_account.id
    async def test_submit_reviewed_disposition_not_found(self, client: AsyncClient): response = await client.post(f'/reconciliation/unmatched/{uuid4()}/reviewed-dispositions', json={'intent': 'expense', 'counter_account_id': str(uuid4()), 'category': 'DINING', 'rationale': 'Reviewed source evidence.'}); assert response.status_code == status.HTTP_404_NOT_FOUND; assert 'Transaction' in response.json()['detail']
    async def test_reviewed_disposition_is_idempotent_and_rejects_account_intent_conflict(self, client: AsyncClient, db, test_user: User): _, _, transaction, expense = await _seed_expense_setup(db, test_user, expense_name='Expense - Transport'); income = Account(user_id=test_user.id, name=f'Income - Invalid {uuid4().hex[:8]}', type=AccountType.INCOME, currency='SGD'); db.add(income); await db.commit(); payload = {'intent': 'expense', 'counter_account_id': str(expense.id), 'category': 'TRANSPORT', 'rationale': 'Reviewed transit charge.'}; first = await client.post(f'/reconciliation/unmatched/{transaction.id}/reviewed-dispositions', json=payload); second = await client.post(f'/reconciliation/unmatched/{transaction.id}/reviewed-dispositions', json=payload); assert first.status_code == status.HTTP_200_OK; assert second.status_code == status.HTTP_200_OK; assert second.json()['id'] == first.json()['id']; conflict = await client.post(f'/reconciliation/unmatched/{transaction.id}/reviewed-dispositions', json={**payload, 'rationale': 'A different evidence review must not rewrite the posted decision.'}); assert conflict.status_code == status.HTTP_400_BAD_REQUEST; assert 'incompatible' in conflict.json()['detail'].lower(); traces = await db.execute(select(TraceRecordRow).where(TraceRecordRow.target_id == str(transaction.id))); assert len(traces.scalars().all()) == 4; incompatible_account = await client.post(f'/reconciliation/unmatched/{transaction.id}/reviewed-dispositions', json={**payload, 'counter_account_id': str(income.id)}); assert incompatible_account.status_code == status.HTTP_400_BAD_REQUEST
    async def test_reviewed_disposition_rejects_unmatched_bypasses_without_persisting(self, client: AsyncClient, db, test_user: User):
        _, statement, transfer_txn, expense = await _seed_expense_setup(db, test_user, expense_name='Expense - Matched Target'); asset = Account(user_id=test_user.id, name=f'Asset - Transfer Target {uuid4().hex[:8]}', type=AccountType.ASSET, currency='SGD'); matched_txn = create_test_transaction(db, statement)
        match = create_test_match(db, matched_txn); db.add_all([asset, matched_txn, match]); await db.commit(); transfer = await client.post(f'/reconciliation/unmatched/{transfer_txn.id}/reviewed-dispositions', json={'intent': 'transfer', 'counter_account_id': str(asset.id), 'rationale': 'The account-to-account transfer requires a matched pair.'}); matched = await client.post(f'/reconciliation/unmatched/{matched_txn.id}/reviewed-dispositions', json={'intent': 'expense', 'counter_account_id': str(expense.id), 'category': 'DINING', 'rationale': 'This transaction already has a reconciliation decision.'}); assert transfer.status_code == status.HTTP_400_BAD_REQUEST; assert 'transfer_unmatched' in transfer.json()['detail']; assert matched.status_code == status.HTTP_400_BAD_REQUEST; assert 'already has a reconciliation match' in matched.json()['detail']
        for transaction_id in (transfer_txn.id, matched_txn.id): entries = await db.execute(select(JournalEntry).where(JournalEntry.source_id == transaction_id)); assert entries.scalars().all() == []
