async def _create_approved_statement(db, user: User) -> StatementSummary:
    custody = await create_test_asset_account(db, user); today = date.today()
    return await create_test_statement(db, user, account_id=custody.id, period_start=today, period_end=today, opening_balance=Decimal('0.00'), closing_balance=Decimal('0.00'), status=BankStatementStatus.APPROVED)
async def test_run_reconciliation_maps_processing_currency_conflict_to_400(client: AsyncClient, monkeypatch: pytest.MonkeyPatch) -> None:
    async def fail_matching(*_args, **_kwargs): raise ValidationError('Processing account currency is SGD; got transfer currency USD')
    monkeypatch.setattr('src.routers.reconciliation.execute_matching', fail_matching)
    response = await client.post('/reconciliation/runs', json={}); assert response.status_code == 400; assert 'Processing account currency is SGD' in response.json()['detail']
async def test_run_reconciliation_filters_unmatched(client: AsyncClient, db, test_user: User, monkeypatch: pytest.MonkeyPatch) -> None:
    statement, _ = await _seed_router_txns(db, test_user, count=1)
    async def fake_execute_matching(*_args, **_kwargs): return [ReconciliationMatch(atomic_txn_id=uuid4(), journal_entry_ids=[], match_score=90, score_breakdown={}, status=ReconciliationStatus.AUTO_ACCEPTED), ReconciliationMatch(atomic_txn_id=uuid4(), journal_entry_ids=[], match_score=70, score_breakdown={}, status=ReconciliationStatus.PENDING_REVIEW)]
    monkeypatch.setattr('src.routers.reconciliation.execute_matching', fake_execute_matching); resp = await client.post('/reconciliation/runs', json={'statement_id': str(statement.id)}); assert resp.status_code == 200; response = resp.json(); assert response['matches_created'] == 2; assert response['auto_accepted'] == 1; assert response['pending_review'] == 1; assert response['unmatched'] == 1
async def test_reconciliation_stats_bucket_distribution(client: AsyncClient, db, test_user: User) -> None:
    statement = await _create_approved_statement(db, test_user); txns = [create_test_transaction(db, statement, amount=Decimal(str(10 + i))) for i in range(4)]; db.add_all(txns); await db.flush()
    matches = [create_test_match(db, txn, match_score=score, status=ReconciliationStatus.AUTO_ACCEPTED if score >= 80 else ReconciliationStatus.PENDING_REVIEW) for txn, score in zip(txns, [55, 70, 85, 95])]; db.add_all(matches); await db.commit()
    resp = await client.get('/reconciliation/stats'); assert resp.status_code == 200; stats = resp.json(); assert stats['total_transactions'] == 4; assert stats['matched_transactions'] == 2; assert stats['match_rate'] == 50.0; assert stats['score_distribution'] == {'0-59': 1, '60-79': 1, '80-89': 1, '90-100': 1}
async def test_accept_reject_batch_accept(client: AsyncClient, db, test_user: User) -> None:
    account, statement, txn1, expense = await _seed_expense_setup(db, test_user); txn2 = create_test_transaction(db, statement, amount=Decimal('8.00')); txn3 = create_test_transaction(db, statement, amount=Decimal('9.00')); db.add_all([txn2, txn3]); await db.flush()
    e1 = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=txn1.txn_date, memo='Accept', amount=txn1.amount); e2 = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=txn2.txn_date, memo='Reject', amount=txn2.amount); e3 = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=txn3.txn_date, memo='Batch', amount=txn3.amount)
    m_accept = create_test_match(db, txn1, journal_entry_ids=[str(e1.id)], match_score=85); m_reject = create_test_match(db, txn2, journal_entry_ids=[str(e2.id)], match_score=75); m_batch = create_test_match(db, txn3, journal_entry_ids=[str(e3.id)], match_score=90); db.add_all([m_accept, m_reject, m_batch]); await db.commit()
    accepted = await client.patch(f'/reconciliation/matches/{m_accept.id}', json={'action': 'accept'}); rejected = await client.patch(f'/reconciliation/matches/{m_reject.id}', json={'action': 'reject'}); batch = await client.post('/reconciliation/matches', json={'action': 'accept', 'match_ids': [str(m_batch.id)]}); assert accepted.status_code == 200; assert rejected.status_code == 200; assert batch.status_code == 200; assert accepted.json()['status'] == ReconciliationStatusEnum.ACCEPTED.value; assert rejected.json()['status'] == ReconciliationStatusEnum.REJECTED.value; assert batch.json()['approved_count'] == 1
async def test_unmatched_exclusions_are_tenant_scoped(client: AsyncClient, db, test_user: User) -> None:
    statement = await _create_approved_statement(db, test_user); source_collision = create_test_transaction(db, statement, amount=Decimal('4.00')); visible = create_test_transaction(db, statement, amount=Decimal('5.00')); db.add_all([source_collision, visible]); other_user = await UserFactory.create_async(db); other_stmt = await _create_approved_statement(db, other_user); other_txn = create_test_transaction(db, other_stmt, amount=Decimal('6.00')); db.add(other_txn); await db.flush(); db.add_all([JournalEntry(user_id=other_user.id, entry_date=date.today(), memo='Foreign source-id collision', source_type=JournalEntrySourceType.AUTO_PARSED, source_id=source_collision.id, status=JournalEntryStatus.DRAFT), create_test_match(db, other_txn, match_score=Decimal('80'))]); await db.commit()
    resp = await client.get('/reconciliation/unmatched', params={'limit': 50, 'offset': 0}); assert resp.status_code == 200; unmatched = resp.json(); assert unmatched['total'] == 2; assert {item['id'] for item in unmatched['items']} == {str(source_collision.id), str(visible.id)}
